SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0900000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 90, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "90", "printedPageNumber": 90, "pdfPageNumber": 473, "sequenceIndex": 80, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0900100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VII", "sourceIdentifier": "VII", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0900000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "the Prophet (Sallallaho alaihe wasallam) said, ''Seek refuge in Allah from sanctimonious devotion.'' We inquired, ''What is sanctimonious devotion, O Prophet of Allah! (Sallallaho alaihe wasallam).'' He replied, ''To feign concentration, with nifaaq lurking in the heart.''\n\nHadhrat Abu Darda (Radhiyallaho anho) relates a similar hadith in which the Prophet (Sallallaho alaihe wasallam) is reported to have said, \"Hypocritical devotion is that in which a person outwardly pretends concentration, while his heart is devoid of that.\"\n\nHadhrat Qataadah (Radhiyallaho anho) says, \"For devotion in salaat, the heart should be full of Allah''s fear, and the gaze should be kept down.\"\n\nThe Prophet (Sallallaho alaihe wasallam) once saw a person fondling his beard while in salaat. He remarked, \"If his heart were blessed with devotion, then his entire body would be at rest.\"\n\nHadhrat Aa''ishah (Radhiyallaho anha) once inquired from the Prophet (Sallallaho alaihe wasallam) as to what his opinion was about the practice of looking around while in salaat. He said, \"It is a damage to salaat caused by Satan.\"\n\nOnce the Prophet (Sallallaho alaihe wasallam) said, \"People in the habit of looking up while in salaat must give up that habit, lest their gaze may become fixed and not return to them.\"\n\nIt has been said by many of the companions and their successors that devotion means tranquillity in salaat. The Prophet (Sallallaho alaihe wasallam) is reported (by many narrators) to have said, \"Offer each salaat (with) such (devotion) as if it were the last salaat of your life.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900200-0000-4000-8000-000000000001", "structuralNodeId": "b0900100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900300-0000-4000-8000-000000000001", "structuralNodeId": "b0900100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن عمران بن حصين رضي الله عنه قال سئل النبي ﷺ عن قول الله تعالى إن الصلاة تنهى عن الفحشاء والمنكر فقال من لم تنهه صلاته عن الفحشاء والمنكر فلا صلاة له كذا في الدر المنثور", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900400-0000-4000-8000-000000000001", "structuralNodeId": "b0900100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Imraan bin Husain (Radhiyallaho anho) narrates, Someone inquired of the Prophet (Sallallaho alaihe wasallam) about the meaning of the verse in Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}]}'::jsonb);